#include "vfs.h"
static size_t slen(const char*s,size_t max){size_t n=0;if(!s)return max;while(n<max&&s[n])n++;return n;}
static int eq(const char*a,const char*b){size_t i=0;if(!a||!b)return 0;while(a[i]&&b[i]&&a[i]==b[i])i++;return a[i]==b[i];}
static void cp(char*d,const char*s,size_t cap){size_t i=0;if(!cap)return;while(i+1<cap&&s[i]){d[i]=s[i];i++;}d[i]=0;}
static int valid_path(const char*p){size_t n=slen(p,VFS_PATH_MAX);if(!p||n==0||n>=VFS_PATH_MAX||p[0]!='/')return 0;if(n==1)return 1;for(size_t i=0;i<n;i++){if((unsigned char)p[i]<32||p[i]=='\\')return 0;if(p[i]=='/'&&i+1<n&&p[i+1]=='/')return 0;if(p[i]=='.'&&(i==0||p[i-1]=='/')&&p[i+1]=='.'&&(p[i+2]=='/'||p[i+2]==0))return 0;}return 1;}
int vfs_init(vfs_t*fs){if(!fs)return -1;fs->count=1;vfs_node_t*r=&fs->nodes[0];cp(r->name,"/",VFS_NAME_MAX);r->type=VFS_DIRECTORY;r->data=0;r->size=0;return 0;}
static int find(const vfs_t*fs,const char*path){if(!fs||!path)return -1;for(size_t i=0;i<fs->count;i++)if(eq(fs->nodes[i].name,path))return (int)i;return -1;}
static int mkdir_path(vfs_t*fs,const char*path){if(!valid_path(path)||path[0]!='/'||eq(path,"/"))return eq(path,"/")?0:-1;int found=find(fs,path);if(found>=0)return fs->nodes[found].type==VFS_DIRECTORY?0:-1;if(fs->count>=VFS_MAX_NODES)return -1;char parent[VFS_PATH_MAX];size_t n=slen(path,VFS_PATH_MAX),last=n;while(last>1&&path[last-1]!='/')last--;size_t plen=(last<=1)?1:last-1;for(size_t i=0;i<plen;i++)parent[i]=path[i];parent[plen]=0;int pi=find(fs,parent);if(pi<0||fs->nodes[pi].type!=VFS_DIRECTORY)return -1;vfs_node_t*x=&fs->nodes[fs->count++];cp(x->name,path,VFS_NAME_MAX);x->type=VFS_DIRECTORY;x->data=0;x->size=0;return 0;}
int vfs_mkdir(vfs_t*fs,const char*path){return mkdir_path(fs,path);}
int vfs_add_file(vfs_t*fs,const char*path,const void*data,size_t size){if(!fs||!valid_path(path)||eq(path,"/")||(!data&&size)||size>VFS_FILE_MAX||find(fs,path)>=0)return -1;size_t n=slen(path,VFS_PATH_MAX),last=n;while(last>1&&path[last-1]!='/')last--;size_t plen=(last<=1)?1:last-1;char parent[VFS_PATH_MAX];for(size_t i=0;i<plen;i++)parent[i]=path[i];parent[plen]=0;if(mkdir_path(fs,parent))return -1;if(fs->count>=VFS_MAX_NODES)return -1;vfs_node_t*x=&fs->nodes[fs->count++];cp(x->name,path,VFS_NAME_MAX);x->type=VFS_REGULAR;x->data=(const uint8_t*)data;x->size=size;return 0;}
int vfs_stat(const vfs_t*fs,const char*path,vfs_node_t*out){if(!valid_path(path)||!out)return -1;int i=find(fs,path);if(i<0)return -1;*out=fs->nodes[i];return 0;}
int vfs_open(const vfs_t*fs,const char*path,vfs_handle_t*out){vfs_node_t n;if(!out||vfs_stat(fs,path,&n)||n.type!=VFS_REGULAR)return -1;out->node=&fs->nodes[find(fs,path)];out->offset=0;return 0;}
size_t vfs_read(vfs_handle_t*h,void*dst,size_t cap){if(!h||!h->node||(!dst&&cap)||h->node->type!=VFS_REGULAR||h->offset>h->node->size)return 0;size_t rem=h->node->size-h->offset,n=rem<cap?rem:cap;const uint8_t*s=h->node->data+h->offset;uint8_t*d=(uint8_t*)dst;for(size_t i=0;i<n;i++)d[i]=s[i];h->offset+=n;return n;}
int vfs_list(const vfs_t*fs,const char*dir,size_t index,vfs_node_t*out){if(!valid_path(dir)||!out)return -1;int di=find(fs,dir);if(di<0||fs->nodes[di].type!=VFS_DIRECTORY)return -1;size_t seen=0,d=slen(dir,VFS_PATH_MAX);for(size_t i=0;i<fs->count;i++){if(i==(size_t)di)continue;const char*p=fs->nodes[i].name;size_t k;if(d==1){if(p[0]!='/')continue;k=1;}else{for(k=0;k<d&&p[k]==dir[k];k++);if(k!=d||p[d]!='/')continue;k=d+1;}if(!p[k])continue;int direct=1;for(size_t j=k;p[j];j++)if(p[j]=='/')direct=0;if(direct&&seen++==index){*out=fs->nodes[i];return 0;}}return -1;}
static uint32_t le32(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
/* GNRD v1: magic, u32 count LE, then path length/path/u32 data length/data. */
int initramfs_mount(vfs_t*fs,const void*image,size_t size){if(!fs||!image||size<8)return -1;const uint8_t*p=(const uint8_t*)image;if(p[0]!='G'||p[1]!='N'||p[2]!='R'||p[3]!='D')return -1;uint32_t count=le32(p+4);if(count>VFS_MAX_NODES-1)return -1;size_t off=8;if(vfs_init(fs))return -1;for(uint32_t i=0;i<count;i++){if(off>=size)return -1;size_t plen=p[off++];if(plen<2||plen>=VFS_PATH_MAX||plen>size-off)return -1;char path[VFS_PATH_MAX];for(size_t j=0;j<plen;j++)path[j]=(char)p[off+j];path[plen]=0;off+=plen;if(size-off<4)return -1;uint32_t len=le32(p+off);off+=4;if(len>size-off||len>VFS_FILE_MAX||!valid_path(path))return -1;if(vfs_add_file(fs,path,p+off,len))return -1;off+=len;}return off==size?0:-1;}
